## Why This Is Asked
Tests runtime extensibility and correctness of flag evaluation, including versioning and thread-safety.

## Key Concepts
- Strategy pattern for evaluation logic
- Registry/Factory for runtime additions
- Thread-safety and version-keying
- Performance implications of dynamic dispatch

## Code Example
```typescript
interface User { id: string; segments: string[]; }
interface Flag { name: string; version: string; defaultValue?: boolean; }

interface FlagEvaluationStrategy {
  evaluate(user: User, flag: Flag): boolean;
}
type StrategyFactory = () => FlagEvaluationStrategy;

class FlagRegistry {
  private map = new Map<string, StrategyFactory>();
  register(key: string, factory: StrategyFactory) { this.map.set(key, factory); }
  get(key: string): FlagEvaluationStrategy {
    const f = this.map.get(key);
    if (!f) throw new Error(`No strategy registered for ${key}`);
    return f();
  }
}
class FlagEvaluator {
  constructor(private registry: FlagRegistry) {}
  eval(flag: Flag, user: User): boolean {
    const strat = this.registry.get(`${flag.name}|${flag.version}`);
    return strat.evaluate(user, flag);
  }
}
class PercentStrategy implements FlagEvaluationStrategy {
  constructor(private percent: number) {}
  evaluate(user: User, flag: Flag): boolean {
    const r = (parseInt(user.id.slice(-4), 10) % 100) < this.percent;
    return r;
  }
}
```
